   "order": 1,
   "r_construct": "read.csv(..., quote = \"\\\"'\", stringsAsFactors = FALSE)",
   "python_approach": "pd.read_csv(path) (default quotechar '\"'), then strip one pair of surrounding single quotes from every object column (s.str.replace(r\"^'(.*)'$\", r\"\\1\", regex=True)); apply R make.names to headers (no-op here). Keep RangeIndex = raw row position.",
   "rule_ids": [
    "R-IO-01",
    "R-IO-03"
   ]
  },
  {
   "order": 2,
   "r_construct": "pmin(ClaimNb, 4); pmin(Exposure, 1)",
   "python_approach": "df['ClaimNb'] = np.minimum(df['ClaimNb'], 4).astype(float); df['Exposure'] = np.minimum(df['Exposure'], 1.0), in R order.",
   "rule_ids": [
    "R-REC-02"
   ]
  },
  {
   "order": 3,
   "r_construct": "as.integer(factor(Area))",
   "python_approach": "levels = sorted unique Area strings (A..F); AreaGLM = position in that list + 1 (int).",
   "rule_ids": [
    "R-FAC-01",
    "R-REC-02"
   ]
  },
  {
   "order": 4,
   "r_construct": "as.factor(pmin(VehPower, 9))",
   "python_approach": "VehPowerGLM = np.minimum(VehPower, 9) as string; dummies from captured levels ['4'..'9'], reference '4'.",
   "rule_ids": [
    "R-FAC-01",
    "R-FAC-02"
   ]
  },
  {
   "order": 5,
   "r_construct": "lookup VehAgeGLM[VehAge + 1, 2] + relevel(ref='2')",
   "python_approach": "Vectorised lookup array over 0..110 = [1, 2*10, 3*100]; index VehAge (0-based = R row VehAge+1); out-of-range -> NaN. Levels from xlevels ['2','1','3'].",
   "rule_ids": [
    "R-IDX-01",
    "R-FAC-01",
    "R-FAC-02"
   ]
  },
  {
   "order": 6,
   "r_construct": "lookup DrivAgeGLM[DrivAge - 17, 2] + relevel(ref='5')",
   "python_approach": "Lookup array over ages 18..100 = [1*3, 2*5, 3*5, 4*10, 5*10, 6*20, 7*30]; index DrivAge-18 (0-based); out-of-range -> NaN. Levels from xlevels ['5','1','2','3','4','6','7']. Kept as-is although age is protected.",
   "rule_ids": [
    "R-IDX-01",
    "R-FAC-01",
    "R-FAC-02",
    "GOV-01"
   ]
  },
  {
   "order": 7,
   "r_construct": "as.integer(pmin(BonusMalus, 150)); as.numeric(log(Density))",
   "python_approach": "np.minimum(BonusMalus, 150); np.log(Density) as float.",
   "rule_ids": [
    "R-REC-02"
   ]
  },
  {
   "order": 8,
   "r_construct": "relevel(as.factor(VehBrand), 'B1'); relevel(as.factor(Region), 'R24'); as.factor(VehGas)",
   "python_approach": "Keep the string columns; design dummies '<var><level>' for every captured level except the first (B1, R24, Diesel).",
   "rule_ids": [
    "R-FAC-01",
    "R-FAC-02"
   ]
  },
  {
   "order": 9,
   "r_construct": "set.seed(100); sample(...) learn/test split",
   "python_approach": "Not implemented. fit() receives the harness-supplied training rows.",
   "rule_ids": [
    "R-RNG-01"
   ]
  },
  {
   "order": 10,
   "r_construct": "glm(ClaimNb ~ ..., offset = log(Exposure), family = poisson()) with default glm.control",
   "python_approach": "numpy IRLS mirroring glm.fit for poisson(log): mustart = y + 0.1, eta = log(mustart) (offset not subtracted at start, as glm.fit), z = (eta - offset) + (y - mu)/mu, w = sqrt(mu), coef from QR of X*w, eta = X@coef + offset, deviance 2*sum(y*log(y/mu) [0 when y=0] - (y - mu)), stop when |dev - dev_old|/(|dev| + 0.1) < 1e-8, maxit 25; SEs from the last iteration's R factor (dispersion 1). Design columns: '(Intercept)' first, then terms in R model.matrix order.",
   "rule_ids": [
    "R-EST-02",
    "R-EST-03",
    "R-FAC-04"
   ]
  },
  {
   "order": 11,
   "r_construct": "predict(d.glm1, newdata, type='response')",
   "python_approach": "exp(X_new @ coef + log(Exposure_capped)) using the same design function; the offset is evaluated in newdata as R does. NaN if any design value is NaN.",
   "rule_ids": [
    "R-PRED-01",
    "R-EST-03"
   ]
  }
 ],
